  function findTool(name) {
    for (var i = 0; i < TOOLS.length; i++) if (TOOLS[i].name === name) return TOOLS[i];
    return null;
  }

  function toOpenAITools() {
    return TOOLS.map(function (tool) {
      return {
        type: 'function',
        function: { name: tool.name, description: tool.description, parameters: tool.parameters },
      };
    });
  }

  /* 工具名 → 词条键（键名以 extension/public/_locales 为准；snapshot 免确认，无对应词条） */
  var TOOL_KEYS = {
    click: 'toolClick',
    type: 'toolType',
    select: 'toolSelect',
    scroll: 'toolScroll',
    read_text: 'toolReadText',
    read_html: 'toolReadHtml',
    page_source: 'toolPageSource',
    extract_table: 'toolExtractTable',
    copy: 'toolCopy',
    edit_text: 'toolEditText',
    edit_html: 'toolEditHtml',
    set_attribute: 'toolSetAttr',
    remove_element: 'toolRemoveEl',
    hide_element: 'toolHideEl',
    get_texts: 'toolGetTexts',
    translate_page: 'toolTranslatePage',
    get_media: 'toolGetMedia',
    download_media: 'toolDownloadMedia',
    open_in_new_tab: 'toolOpenTab',
  };

  /** 工具显示名：没有词条的（如 snapshot）直接用原名 */
  function toolLabel(name) {
    var key = TOOL_KEYS[name];
    return key ? t(key) : name;
  }

  /** 快照元素描述：优先文本，其次 aria，最后 <tag>；再补 tag 与 selector */
  function elementDesc(args, elements) {
    if (args && typeof args.index === 'number' && elements && elements[args.index]) {
      var el = elements[args.index];
      return (el.text || el.aria || '<' + el.tag + '>') + ' (' + el.tag + ', ' + el.selector + ')';
    }
    if (args && args.selector) return args.selector;
    return '';
  }

  /**
   * 白名单 + 参数校验（对应 core/tools.ts 的 validateToolCall，逐条复刻）。
   * 返回 {ok:true, call:{tool,args}} 或 {ok:false, error}
   */
  function validateToolCall(raw) {
    if (!raw || typeof raw !== 'object') return { ok: false, error: '工具调用不是对象' };
    if (typeof raw.tool !== 'string') return { ok: false, error: '缺少工具名' };
    var def = findTool(raw.tool);
    if (!def) return { ok: false, error: '不在白名单内：' + raw.tool };
    var args = raw.args && typeof raw.args === 'object' ? Object.assign({}, raw.args) : {};

    if (def.needsTarget) {
      var hasIndex = typeof args.index === 'number' && Number.isInteger(args.index) && args.index >= 0;
      var hasSel = typeof args.selector === 'string' && args.selector.length > 0;
      if (!hasIndex && !hasSel) return { ok: false, error: raw.tool + ' 需要 index 或 selector' };
      if (!hasIndex) delete args.index;
    }

    if (raw.tool === 'type' || raw.tool === 'select' || raw.tool === 'open_in_new_tab') {
      if (typeof args.text !== 'string' || !args.text.length) return { ok: false, error: raw.tool + ' 需要 text' };
      if (args.text.length > 2000) return { ok: false, error: 'text 过长（>2000 字符）' };
      if (raw.tool === 'open_in_new_tab' && !/^https?:\/\//i.test(args.text)) {
        return { ok: false, error: 'open_in_new_tab 只允许 http(s) 链接' };
      }
    }
    if (raw.tool === 'edit_text') {
      if (typeof args.text !== 'string' || !args.text.length) return { ok: false, error: 'edit_text 需要 text' };
      if (args.text.length > 2000) return { ok: false, error: 'text 过长（>2000 字符）' };
    }
    if (raw.tool === 'edit_html') {
      if (typeof args.html !== 'string' || !args.html.length) return { ok: false, error: 'edit_html 需要 html' };
      if (args.html.length > 20000) return { ok: false, error: 'html 过长（>20000 字符）' };
    }
    if (raw.tool === 'set_attribute') {
      if (typeof args.name !== 'string' || !args.name.length || args.name.length > 64) {
        return { ok: false, error: 'set_attribute 需要合法的属性名' };
      }
      if (/^on/i.test(args.name) || /^(srcdoc|formaction)$/i.test(args.name)) {
        return { ok: false, error: '该属性被禁止' };
      }
      if (typeof args.value !== 'string' || args.value.length > 4000) {
        return { ok: false, error: 'set_attribute 需要 value（≤4000 字符）' };
      }
      if (
        /^(href|src|xlink:href|action|poster)$/i.test(args.name) &&
        /^\s*(javascript|vbscript|data):/i.test(args.value)
      ) {
        return { ok: false, error: 'URL 类属性仅允许 http(s) 或相对地址' };
      }
    }
    if (raw.tool === 'translate_page') {
      if (typeof args.lang !== 'string' || !args.lang.length || args.lang.length > 16) {
        return { ok: false, error: 'translate_page 需要 lang' };
      }
      var rawItems = args.items;
      if ((!Array.isArray(rawItems) || !rawItems.length) && typeof args.items_json === 'string') {
        try {
          rawItems = JSON.parse(args.items_json);
        } catch (e) {
          return { ok: false, error: 'items_json 不是合法的 JSON 字符串' };
        }
      }
      if (!Array.isArray(rawItems) || !rawItems.length || rawItems.length > 1000) {
        return { ok: false, error: 'translate_page 需要 items_json（1-1000 条）' };
      }
      var items = [];
      for (var i = 0; i < rawItems.length; i++) {
        var it = rawItems[i];
        if (!it || typeof it !== 'object') return { ok: false, error: 'items 条目格式错误' };
        if (typeof it.index !== 'number' || !Number.isInteger(it.index) || it.index < 0) {
          return { ok: false, error: 'items[index] 必须是整数' };
        }
        if (typeof it.text !== 'string' || !it.text.length || it.text.length > 1500) {
          return { ok: false, error: 'items[text] 需为 1-1500 字符' };
        }
        items.push({ index: it.index, text: it.text });
      }
      args.items = items;
    }
    if (raw.tool === 'download_media') {
      if (typeof args.url !== 'string' || !/^https?:\/\//i.test(args.url)) {
        return { ok: false, error: 'download_media 需要合法的 http(s) url' };
      }
      if (args.url.length > 2000) return { ok: false, error: 'url 过长' };
    }
    if (raw.tool === 'scroll') {
      if (typeof args.amount !== 'number' || !isFinite(args.amount)) {
        return { ok: false, error: 'scroll 需要数值 amount' };
      }
      // 静默钳制而非报错（与扩展版一致）
      args.amount = Math.max(-5000, Math.min(5000, args.amount));
    }
    return { ok: true, call: { tool: raw.tool, args: args } };
  }

